<?php namespace Workspace; ?>
<p class="lede">UK sole trader · VAT 20% · GBP · внутренние B2B-услуги. Реестр исходящего VAT, не налоговая декларация. Перед включением проверьте регистрацию и применимость режима с бухгалтером.</p>
<section class="panel"><h2>Профили продавцов</h2><p>Реквизиты продавца берутся из раздела <a href="<?= h(url('invoices')) ?>">Счета</a>. Название и адрес должны совпадать с VAT-регистрацией. После изменения реквизитов требуется новое согласование.</p>
<?php foreach($profiles as $p): ?><details class="editor"><summary><?= h($p['name']) ?> · <?= !$p['profile_version']?'Не настроен':($p['approved_at']&&$p['effective_on']<=ukToday()&&$p['reviewed_until']>=ukToday()&&(int)$p['entity_version']===(int)$p['version']?'Действует':'Не активен / требует проверки') ?></summary>
<?php if($user['role']==='owner'): ?><form method="post" class="formgrid"><?php formFields('tax.prepare') ?><input type="hidden" name="entity_id" value="<?= h($p['id']) ?>"><input type="hidden" name="version" value="<?= h($p['profile_version']??'') ?>"><label>VAT number<input name="vat_number" value="<?= h($p['vat_number']??'') ?>" maxlength="20" required></label><label>Полное имя sole trader<input name="proprietor" value="<?= h($p['proprietor']??'') ?>" maxlength="180" required></label><label>Контакты продавца<input name="contact" value="<?= h($p['contact']??'') ?>" maxlength="180" required></label><label>Адрес вручения юридических документов<input name="service_address" value="<?= h($p['service_address']??'') ?>" maxlength="500" required></label><label>Начало действия<input name="effective_on" type="date" value="<?= h(ukToday()) ?>" required></label><label>Проверено до<input name="reviewed_until" type="date" value="<?= h($p['reviewed_until']??(new \DateTimeImmutable(ukToday()))->modify('+90 days')->format('Y-m-d')) ?>" required></label><button class="primary">Передать бухгалтеру (блокирует выставление до согласования)</button></form><?php endif ?>
<?php if($p['profile_version']): ?><p>VAT <?= h($p['vat_number']) ?> · <?= h($p['proprietor']) ?> · <?= h($p['contact']) ?> · <?= h($p['service_address']) ?> · <?= h($p['effective_on']) ?> — <?= h($p['reviewed_until']) ?></p><?php endif ?>
<?php if($user['role']==='accountant'&&$p['profile_version']&&!$p['approved_at']): ?><form method="post" class="formgrid"><?php formFields('tax.approve') ?><input type="hidden" name="entity_id" value="<?= h($p['id']) ?>"><input type="hidden" name="version" value="<?= h($p['profile_version']) ?>"><label>Ссылка/номер свидетельства проверки и эталонных примеров<input name="review_reference" required maxlength="500"></label><label><input type="checkbox" name="confirmed" value="1" required> Проверены регистрация, реквизиты, применимость UK standard VAT и контрольные расчёты, включая кредит-ноту</label><button class="primary">Подтвердить профиль</button></form><?php endif ?></details><?php endforeach ?></section>
<section class="panel"><h2>Реестр исходящего VAT</h2><form method="get" class="filters"><input type="hidden" name="p" value="tax"><label>С<input type="date" name="from" value="<?= h($from) ?>" required></label><label>По<input type="date" name="to" value="<?= h($to) ?>" required></label><button>Сформировать</button></form><p><a href="<?= h(url('tax.export',['from'=>$from,'to'=>$to])) ?>">Скачать CSV для бухгалтера</a> · Счетов без VAT-пакета за период: <?= h($legacy) ?> (не включены, проверьте отдельно).</p><?php foreach($totals as $eid=>$t): ?><p>Продавец #<?= h($eid) ?> · Без VAT: <?= h(money($t['net'])) ?> GBP · Исходящий VAT: <?= h(money($t['vat'])) ?> GBP · С VAT: <?= h(money($t['gross'])) ?> GBP</p><?php endforeach ?>
<div class="tablewrap"><table><thead><tr><th>Документ</th><th>Дата</th><th>Без VAT</th><th>VAT</th><th>С VAT</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><a href="<?= h(url('tax.print',['project'=>$r['project_id'],'id'=>$r['invoice_id'],'credit'=>$r['kind']==='credit'?1:0])) ?>"><?= h($r['doc_number']) ?></a></td><td><?= h($r['date']) ?></td><td><?= h(money($r['net'])) ?></td><td><?= h(money($r['vat'])) ?></td><td><?= h(money($r['gross'])) ?></td></tr><?php endforeach ?></tbody></table></div></section>
